import React from 'react';

import CommentsWidget from '@apps/Comments/components/CommentsWidget';
import PageLoader from '@components/PageLoader';
import { err } from '@helpers/notificationHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohContainer from '@ui-kit/layout/Container';
import PohTabs, { IPohTab } from '@ui-kit/Tabs';

import { getHikingDataAsync } from '../../@services/hiking.service';
import { IHikingData } from '../../@types/hiking.types';

interface IHikingCommentsPageProps {
  id_hiking: number;
}

const HikingCommentsPage: React.FC<IHikingCommentsPageProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);

  React.useEffect(() => {
    const init = async () => {
      await getHikingDataAsync(id_hiking).then(setHikingData);
    };

    init().catch(err);
  }, [id_hiking]);

  if (hikingData == null) {
    return <PageLoader />;
  }

  const tabs = hikingData.hikers.reduce<IPohTab[]>(
    (acc, hiker) => {
      return acc.concat(
        ...hiker.positions
          .filter((pos) => !acc.find((p) => p.key === pos.id))
          .map((pos) => {
            return {
              key: pos.id,
              title: pos.name,
              content: (
                <div>
                  <blockquote className="pt-2">
                    Обсуждаем в ветке вопросы актальные для должности «{pos.name}»
                    <br />
                    <small className="text-muted">
                      отв. {hiker.name} {hiker.surname}
                    </small>
                  </blockquote>
                  <CommentsWidget
                    id_hiking={id_hiking}
                    id_position={pos.id}
                    startText="Создать ветку чата"
                  />
                </div>
              ),
            } as IPohTab;
          }),
      );
    },
    [
      {
        key: 'hiking',
        title: 'ПОХОД',
        content: (
          <div>
            <blockquote className="pt-2">Обсуждаем в ветке общие вопросы по походу</blockquote>
            <CommentsWidget id_hiking={id_hiking} startText="Создать ветку чата" />
          </div>
        ),
      },
    ],
  );

  return (
    <PohContainer>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/comments`, text: 'Комментарии похода', active: true },
        ]}
      />
      <h3 className="mb-3">Комментарии &laquo;{hikingData.name}&raquo;</h3>
      <PohTabs tabs={tabs} useHash></PohTabs>
    </PohContainer>
  );
};
export default HikingCommentsPage;
